def transform(grid):
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        zeros = [j for j, x in enumerate(row) if x == 0]
        for a, b in zip(zeros, zeros[1:]):
            for j in range(a + 1, b):
                if row[j] == 5:
                    out[i][j] = 2
    return out
